  const s = Array.from(text)
  const n = s.length
  let i = 0
  let line = 1
  let col = 1
  const toks = []
  const pos = () => ({ line, col })
  const adv = () => {
    const c = s[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = (Math.floor(col / 4) + 1) * 4 + 1
    else col++
    return c
