    if (!ok(s[j])) return j
    j++
    for (;;) {
      if (ok(s[j])) j++
      else if (s[j] === '_' && ok(s[j + 1])) j += 2
      else return j
    }
  }

  while (i < n) {
    const c = s[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && s[i + 1] === '/') {
      while (i < n && s[i] !== '\n') adv()
      continue
    }
    if (c === '/' && s[i + 1] === '*') {
      const start = pos()
      let depth = 0
      do {
        if (i >= n) throw new ScanError(start, 'unterminated block comment')
        if (s[i] === '/' && s[i + 1] === '*') { depth++; advN(2) }
        else if (s[i] === '*' && s[i + 1] === '/') { depth--; advN(2) }
        else adv()
      } while (depth > 0)
      continue
    }
    const start = pos()
    if (c === 'r' && s[i + 1] === '"') {
      let j = i + 2
      while (j < n && s[j] !== '"') j++
      if (j >= n) throw new ScanError(start, 'unterminated string')
      const body = s.slice(i + 2, j).join('')
      advN(j + 1 - i)
      toks.push({ ...start, kind: 'rawstring', body: JSON.stringify(body) })
      continue
    }
    if (isLetter(c) || c === '_') {
      let j = i
      while (isIdCont(s[j])) j++
      const word = s.slice(i, j).join('')
      advN(j - i)
      toks.push({ ...start, kind: KEYWORDS.has(word) ? 'keyword' : 'ident', body: word })
      continue
    }
    if (isDigit(c)) {
      let j = i
      let bad = false
      const p = s[i + 1]
      const base = c === '0' && p !== undefined ? { x: isHex, X: isHex, b: (d) => d === '0' || d === '1', B: (d) => d === '0' || d === '1', o: (d) => d >= '0' && d <= '7', O: (d) => d >= '0' && d <= '7' }[p] : undefined
