      if (bad) {
        while (isIdCont(s[j])) j++
        throw new ScanError(start, `invalid number ${s.slice(i, j).join('')}`)
      }
      const word = s.slice(i, j).join('')
      advN(j - i)
      toks.push({ ...start, kind: 'number', body: word })
      continue
    }
    if (c === '"') {
      adv()
      let val = ''
      for (;;) {
